dashboard.definition:
{
	"title": "Environment Health",
	"description": "",
	"inputs": {
		"input_global_trp": {
			"options": {
				"defaultValue": "-30d@d,now",
				"token": "global_time"
			},
			"title": "Global Time Range",
			"type": "input.timerange"
		},
		"input_nav_dropdown": {
			"type": "input.dropdown",
			"title": "Navigate to Dashboard",
			"options": {
				"items": [
					{"label": "Overview", "value": "logserv_overview"},
					{"label": "DNS Analytics", "value": "logserv_dns_analytics"},
					{"label": "HANA Audit", "value": "logserv_hana_audit"},
					{"label": "HANA Trace", "value": "logserv_hana_trace"},
					{"label": "Web Dispatcher", "value": "logserv_web_dispatcher"},
					{"label": "Host Details", "value": "logserv_host_details"},
					{"label": "ABAP Security", "value": "logserv_abap_security"},
					{"label": "ABAP Operations", "value": "logserv_abap_operations"},
					{"label": "SAP Services", "value": "logserv_sap_services"},
					{"label": "Cloud Connector", "value": "logserv_cloud_connector"},
					{"label": "Linux", "value": "logserv_linux"},
					{"label": "Windows", "value": "logserv_windows"},
					{"label": "Proxy", "value": "logserv_proxy"}
				],
				"token": "nav_target"
			}
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		}
	},
	"visualizations": {
		"viz_kpi_total_errors": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_total_errors"},
			"title": "Total Errors",
			"options": {
				"majorValue": "> primary | seriesByName('total_errors') | lastPoint()",
				"majorColor": "#dc4e41",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/search?q=index%3Dsap_logserv_logs%20%28%28sourcetype%3D%22sap%3Aabap%3Adispatcher%22%20%28dp_severity%3D%22ERROR%22%20OR%20dp_severity%3D%22FATAL%22%29%29%20OR%20%28sourcetype%3D%22sap%3Aabap%3Aicm%22%20icm_is_error%3D1%29%20OR%20%28sourcetype%3D%22sap%3Aabap%3Agateway%22%20gw_error_detail%21%3D%22%22%29%20OR%20%28sourcetype%3D%22sap%3Ahana%3Aaudit%22%20status%21%3D%22SUCCESSFUL%22%29%20OR%20%28sourcetype%3D%22sap%3Ahana%3Atracelogs%22%20%28hana_trace_severity%3D%22error%22%20OR%20hana_trace_severity%3D%22fatal%22%29%29%20OR%20%28sourcetype%3D%22sap%3Ascc%3Ahttp_access%22%20is_error%3D%22true%22%29%20OR%20%28sourcetype%3D%22sap%3Asapstartsrv%22%20is_auth_event%3D%22true%22%20auth_result%3D%22failure%22%29%20OR%20%28sourcetype%3D%22sap%3Asaprouter%22%20is_error%3D%22true%22%29%20OR%20%28sourcetype%3D%22sap%3Awebdispatcher%3Aaccess%22%20status%3E%3D400%29%20OR%20%28sourcetype%3D%22XmlWinEventLog%22%20%28severity%3D%22high%22%20OR%20severity%3D%22medium%22%29%29%20OR%20%28sourcetype%3D%22linux_secure%22%20IN_DROP%29%20OR%20%28sourcetype%3D%22squid%3Aaccess%22%20action%3D%22denied%22%29%29%20%7C%20eval%20Category%3Dcase%28match%28sourcetype%2C%22sap%3Aabap%22%29%2C%22ABAP%22%2Cmatch%28sourcetype%2C%22sap%3Ahana%22%29%2C%22HANA%22%2Csourcetype%20IN%20%28%22sap%3Asapstartsrv%22%2C%22sap%3Ascc%3Ahttp_access%22%2C%22linux_secure%22%29%2C%22Security%22%2Csourcetype%20IN%20%28%22sap%3Awebdispatcher%3Aaccess%22%2C%22sap%3Asaprouter%22%2C%22squid%3Aaccess%22%29%2C%22Web%2FNetwork%22%2Csourcetype%3D%22XmlWinEventLog%22%2C%22OS%2FInfra%22%2C1%3D1%2C%22Other%22%29%20%7C%20stats%20count%20as%20Errors%20dc%28host%29%20as%20%22Affected%20Hosts%22%20latest%28_time%29%20as%20lt%20by%20Category%20sourcetype%20%7C%20eval%20%22Last%20Seen%22%3Dstrftime%28lt%2C%22%25Y-%25m-%25d%20%25H%3A%25M%22%29%20%7C%20fields%20-%20lt%20%7C%20sort%20-Errors&earliest=$global_time.earliest$&latest=$global_time.latest$&display.page.search.mode=verbose&display.general.type=statistics", "newTab": true}}]
		},
		"viz_kpi_hana_failures": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_hana_failures"},
			"title": "HANA Failed Ops",
			"options": {
				"majorValue": "> primary | seriesByName('failures') | lastPoint()",
				"majorColor": "#dc4e41",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/logserv_hana_audit?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		},
		"viz_kpi_auth_failures": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_auth_failures"},
			"title": "Auth Failures",
			"options": {
				"majorValue": "> primary | seriesByName('auth_failures') | lastPoint()",
				"majorColor": "#dc4e41",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/logserv_sap_services?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		},
		"viz_kpi_firewall_drops": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_firewall_drops"},
			"title": "Firewall Drops",
			"options": {
				"majorValue": "> primary | seriesByName('drops') | lastPoint()",
				"majorColor": "#dc4e41",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/logserv_linux?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		},
		"viz_kpi_web_error_rate": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_web_error_rate"},
			"title": "Web Error Rate %",
			"options": {
				"majorValue": "> primary | seriesByName('error_rate') | lastPoint()",
				"majorColor": "#dc4e41",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/logserv_web_dispatcher?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		},
		"viz_kpi_beaconing": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_beaconing"},
			"title": "Beaconing Domains",
			"options": {
				"majorValue": "> primary | seriesByName('beaconing') | lastPoint()",
				"majorColor": "#f1813f",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/logserv_dns_analytics?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		},
		"viz_err_abap": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_err_abap"},
			"title": "ABAP Error Trend",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColorsByField": {"Dispatcher": "#f1813f", "ICM": "#f8a872", "Gateway": "#d98042"}
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/logserv_abap_security?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		},
		"viz_err_hana": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_err_hana"},
			"title": "HANA Error Trend",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColorsByField": {"Audit Failures": "#dc4e41", "Trace Errors": "#ff7a6b"}
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/logserv_hana_audit?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		},
		"viz_err_security": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_err_security"},
			"title": "Security Error Trend",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColorsByField": {"Auth Failures": "#b50101", "Firewall Drops": "#dc4e41"}
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/logserv_sap_services?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		},
		"viz_err_webnet": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_err_webnet"},
			"title": "Web/Network Error Trend",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColorsByField": {"WebDisp 4xx/5xx": "#0877a6", "Router Errors": "#4fa484", "Proxy Denied": "#6cb4d9"}
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/logserv_web_dispatcher?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		},
		"viz_err_osinfra": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_err_osinfra"},
			"title": "OS/Infra Error Trend",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColorsByField": {"Windows High": "#7b56db", "Windows Medium": "#a88ad4"}
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/logserv_windows?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		},
		"viz_err_scc": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_err_scc"},
			"title": "Cloud Connector Error Trend",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColorsByField": {"4xx Client": "#f1813f", "5xx Server": "#dc4e41"}
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/logserv_cloud_connector?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		},
		"viz_rect_r2b_scc": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_critical_events": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_critical_events"},
			"title": "Recent Critical Events",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			},
			"eventHandlers": [
				{
					"type": "drilldown.linkToDashboard",
					"options": {
						"app": "splunk_app_sap_logserv",
						"dashboard": "logserv_host_details",
						"newTab": false,
						"tokens": [
							{"token": "host_name", "value": "row.Host.value"},
							{"token": "global_time.earliest", "value": "$global_time.earliest$"},
							{"token": "global_time.latest", "value": "$global_time.latest$"}
						]
					}
				}
			]
		},
		"viz_top_hosts": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_top_hosts"},
			"title": "Top Affected Hosts",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			},
			"eventHandlers": [
				{
					"type": "drilldown.linkToDashboard",
					"options": {
						"app": "splunk_app_sap_logserv",
						"dashboard": "logserv_host_details",
						"newTab": false,
						"tokens": [
							{"token": "host_name", "value": "row.Host.value"},
							{"token": "global_time.earliest", "value": "$global_time.earliest$"},
							{"token": "global_time.latest", "value": "$global_time.latest$"}
						]
					}
				}
			]
		},
		"viz_web_response_time": {
			"type": "splunk.line",
			"dataSources": {"primary": "ds_web_response_time"},
			"title": "Web Dispatcher Response Time",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": ["#f1813f"]
			},
			"eventHandlers": [
				{
					"type": "drilldown.customUrl",
					"options": {
						"url": "/app/splunk_app_sap_logserv/logserv_web_dispatcher?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
						"newTab": false
					}
				}
			]
		},
		"viz_icm_status": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_icm_status"},
			"title": "ICM Status Codes",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColorsByField": {
					"2xx": "#4fa484",
					"3xx": "#0877a6",
					"4xx": "#dc4e41",
					"5xx": "#f1813f"
				}
			},
			"eventHandlers": [
				{
					"type": "drilldown.customUrl",
					"options": {
						"url": "/app/splunk_app_sap_logserv/logserv_abap_security?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
						"newTab": false
					}
				}
			]
		},
		"viz_pipeline_health": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_pipeline_health"},
			"title": "Data Pipeline — Events/Day",
			"options": {
				"majorValue": "> primary | seriesByName('avg_daily') | lastPoint()",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			},
			"eventHandlers": [
				{
					"type": "drilldown.customUrl",
					"options": {
						"url": "/app/splunk_app_sap_logserv/logserv_overview?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
						"newTab": false
					}
				}
			]
		},
		"viz_pipeline_trend": {
			"type": "splunk.line",
			"dataSources": {"primary": "ds_pipeline_trend"},
			"title": "Daily Event Volume Trend",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": ["#4fa484"]
			},
			"eventHandlers": [
				{
					"type": "drilldown.customUrl",
					"options": {
						"url": "/app/splunk_app_sap_logserv/logserv_overview?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
						"newTab": false
					}
				}
			]
		},
		"viz_rect_r2a_left": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_r2a_mid": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_r2a_right": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_r2b_left": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_r2b_right": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_row3_left": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_row3_right": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_row4_left": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_row4_mid": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_row4_right": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_nav_go": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_nav_go"},
			"options": {
				"majorValue": "> primary | seriesByName('label') | lastPoint()",
				"backgroundColor": "#0877a6",
				"majorColor": "#ffffff",
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorFontSize": 14
			},
			"eventHandlers": [
				{
					"type": "drilldown.customUrl",
					"options": {
						"url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
						"newTab": false
					}
				}
			]
		}
	},
	"dataSources": {
		"ds_kpi_total_errors": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` ((sourcetype=\"sap:abap:dispatcher\" (dp_severity=\"ERROR\" OR dp_severity=\"FATAL\")) OR (sourcetype=\"sap:abap:icm\" icm_is_error=1) OR (sourcetype=\"sap:abap:gateway\" gw_error_detail=* gw_error_detail!=\"\") OR (sourcetype=\"sap:hana:audit\" status!=\"SUCCESSFUL\") OR (sourcetype=\"sap:hana:tracelogs\" (hana_trace_severity=\"error\" OR hana_trace_severity=\"fatal\")) OR (sourcetype=\"sap:scc:http_access\" is_error=\"true\") OR (sourcetype=\"sap:sapstartsrv\" is_auth_event=\"true\" auth_result=\"failure\") OR (sourcetype=\"sap:saprouter\" is_error=\"true\") OR (sourcetype=\"squid:access\" action=\"denied\") OR (sourcetype=\"sap:webdispatcher:access\") OR (sourcetype=\"XmlWinEventLog\") OR (sourcetype=\"linux_secure\")) | eval is_err=case(sourcetype=\"sap:webdispatcher:access\", if(tonumber(status)>=400, 1, 0), sourcetype=\"XmlWinEventLog\", if(severity IN (\"high\", \"medium\"), 1, 0), sourcetype=\"linux_secure\", if(match(_raw, \"IN_DROP\"), 1, 0), 1=1, 1) | stats sum(is_err) as total_errors"
			}
		},
		"ds_kpi_hana_failures": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"sap:hana:audit\" status!=\"SUCCESSFUL\" | stats count as failures"
			}
		},
		"ds_kpi_auth_failures": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` ((sourcetype=\"sap:sapstartsrv\" is_auth_event=\"true\" auth_result=\"failure\") OR (sourcetype=\"sap:hana:audit\" audit_action=\"CONNECT\" status!=\"SUCCESSFUL\")) | stats count as auth_failures"
			}
		},
		"ds_kpi_firewall_drops": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"linux_secure\" IN_DROP | stats count as drops"
			}
		},
		"ds_kpi_web_error_rate": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"sap:webdispatcher:access\" | eval is_err=if(tonumber(status)>=400,1,0) | stats sum(is_err) as errors count as total | eval error_rate=if(total>0, round(errors/total*100, 1), 0)"
			}
		},
		"ds_kpi_beaconing": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\" | fields _time, query | streamstats current=f last(_time) as last_time by query | eval gap=last_time - _time | stats count avg(gap) AS avg_gap var(gap) AS var_gap BY query | where var_gap < 60 AND count > 2 AND avg_gap > 1 | stats dc(query) as beaconing"
			}
		},
		"ds_err_abap": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` ((sourcetype=\"sap:abap:dispatcher\" (dp_severity=\"ERROR\" OR dp_severity=\"FATAL\")) OR (sourcetype=\"sap:abap:icm\" icm_is_error=1) OR (sourcetype=\"sap:abap:gateway\" gw_error_detail=* gw_error_detail!=\"\")) | eval src=case(sourcetype=\"sap:abap:dispatcher\", \"Dispatcher\", sourcetype=\"sap:abap:icm\", \"ICM\", sourcetype=\"sap:abap:gateway\", \"Gateway\") | timechart span=1d count by src"
			}
		},
		"ds_err_hana": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` ((sourcetype=\"sap:hana:audit\" status!=\"SUCCESSFUL\") OR (sourcetype=\"sap:hana:tracelogs\" (hana_trace_severity=\"error\" OR hana_trace_severity=\"fatal\"))) | eval src=case(sourcetype=\"sap:hana:audit\", \"Audit Failures\", sourcetype=\"sap:hana:tracelogs\", \"Trace Errors\") | timechart span=1d count by src"
			}
		},
		"ds_err_security": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` ((sourcetype=\"sap:sapstartsrv\" is_auth_event=\"true\" auth_result=\"failure\") OR (sourcetype=\"linux_secure\" IN_DROP)) | eval src=case(sourcetype=\"sap:sapstartsrv\", \"Auth Failures\", sourcetype=\"linux_secure\", \"Firewall Drops\") | timechart span=1d count by src"
			}
		},
		"ds_err_scc": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"sap:scc:http_access\" status>=400 | eval src=case(status>=500, \"5xx Server\", status>=400, \"4xx Client\") | timechart span=1d count by src"
			}
		},
		"ds_err_webnet": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` ((sourcetype=\"sap:webdispatcher:access\") OR (sourcetype=\"sap:saprouter\" is_error=\"true\") OR (sourcetype=\"squid:access\" action=\"denied\")) | eval is_err=case(sourcetype=\"sap:webdispatcher:access\", if(tonumber(status)>=400, 1, 0), 1=1, 1) | where is_err=1 | eval src=case(sourcetype=\"sap:webdispatcher:access\", \"WebDisp 4xx/5xx\", sourcetype=\"sap:saprouter\", \"Router Errors\", sourcetype=\"squid:access\", \"Proxy Denied\") | timechart span=1d count by src"
			}
		},
		"ds_err_osinfra": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" (severity=\"high\" OR severity=\"medium\") | eval src=case(severity=\"high\", \"Windows High\", severity=\"medium\", \"Windows Medium\") | timechart span=1d count by src"
			}
		},
		"ds_critical_events": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` ((sourcetype=\"sap:hana:audit\" status!=\"SUCCESSFUL\") OR (sourcetype=\"sap:abap:dispatcher\" (dp_severity=\"ERROR\" OR dp_severity=\"FATAL\")) OR (sourcetype=\"sap:hana:tracelogs\" hana_trace_severity=\"fatal\") OR (sourcetype=\"sap:sapstartsrv\" is_auth_event=\"true\" auth_result=\"failure\") OR (sourcetype=\"XmlWinEventLog\" severity=\"critical\")) | eval Category=case(sourcetype=\"sap:hana:audit\", \"HANA Audit\", sourcetype=\"sap:abap:dispatcher\", \"ABAP Dispatcher\", sourcetype=\"sap:hana:tracelogs\", \"HANA Trace\", sourcetype=\"sap:sapstartsrv\", \"Auth Failure\", sourcetype=\"XmlWinEventLog\", \"Windows Critical\", 1=1, sourcetype) | eval Detail=case(sourcetype=\"sap:hana:audit\", status.\" - \".audit_action.\" by \".executing_user, sourcetype=\"sap:abap:dispatcher\", dp_severity.\" - \".coalesce(dp_message, _raw), sourcetype=\"sap:hana:tracelogs\", hana_trace_severity.\" - \".hana_trace_component, sourcetype=\"sap:sapstartsrv\", \"Auth failure for \".coalesce(auth_user, \"unknown\"), sourcetype=\"XmlWinEventLog\", coalesce(source, \"WinEvent\").\" EventCode=\".coalesce(EventCode, \"N/A\"), 1=1, \"\") | eval Time=strftime(_time, \"%Y-%m-%d %H:%M:%S\") | table Time host Category sourcetype Detail | sort -Time | head 20 | rename host as Host, sourcetype as Sourcetype"
			}
		},
		"ds_top_hosts": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` ((sourcetype=\"sap:abap:dispatcher\" (dp_severity=\"ERROR\" OR dp_severity=\"FATAL\")) OR (sourcetype=\"sap:abap:icm\" icm_is_error=1) OR (sourcetype=\"sap:abap:gateway\" gw_error_detail=* gw_error_detail!=\"\") OR (sourcetype=\"sap:hana:audit\" status!=\"SUCCESSFUL\") OR (sourcetype=\"sap:hana:tracelogs\" (hana_trace_severity=\"error\" OR hana_trace_severity=\"fatal\")) OR (sourcetype=\"sap:scc:http_access\" is_error=\"true\") OR (sourcetype=\"sap:sapstartsrv\" is_auth_event=\"true\" auth_result=\"failure\") OR (sourcetype=\"sap:saprouter\" is_error=\"true\") OR (sourcetype=\"squid:access\" action=\"denied\") OR (sourcetype=\"sap:webdispatcher:access\") OR (sourcetype=\"XmlWinEventLog\") OR (sourcetype=\"linux_secure\")) | eval is_err=case(sourcetype=\"sap:webdispatcher:access\", if(tonumber(status)>=400, 1, 0), sourcetype=\"XmlWinEventLog\", if(severity IN (\"high\", \"medium\"), 1, 0), sourcetype=\"linux_secure\", if(match(_raw, \"IN_DROP\"), 1, 0), 1=1, 1) | where is_err=1 | eval error_cat=case(sourcetype IN (\"sap:abap:dispatcher\",\"sap:abap:icm\",\"sap:abap:gateway\"), \"ABAP\", sourcetype IN (\"sap:hana:audit\",\"sap:hana:tracelogs\"), \"HANA\", sourcetype IN (\"sap:sapstartsrv\",\"sap:saprouter\"), \"Services\", sourcetype IN (\"linux_secure\"), \"Firewall\", 1=1, \"Other\") | chart count by host error_cat | addtotals | sort -Total | head 15 | rename host as Host"
			}
		},
		"ds_web_response_time": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"sap:webdispatcher:access\" | eval response_time_ms=tonumber(total_us)/1000 | timechart span=1d avg(response_time_ms) as \"Avg Response Time (ms)\""
			}
		},
		"ds_icm_status": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:icm\" icm_status_code=* | eval status_cat=case(icm_status_code>=200 AND icm_status_code<300, \"2xx\", icm_status_code>=300 AND icm_status_code<400, \"3xx\", icm_status_code>=400 AND icm_status_code<500, \"4xx\", icm_status_code>=500, \"5xx\", 1=1, \"Other\") | timechart span=1d count by status_cat"
			}
		},
		"ds_pipeline_health": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` | timechart span=1d count as daily_events | stats avg(daily_events) as avg_daily | eval avg_daily=round(avg_daily, 0)"
			}
		},
		"ds_pipeline_trend": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` | timechart span=1d count as \"Events/Day\""
			}
		},
		"ds_nav_go": {
			"type": "ds.search",
			"options": {
				"query": "| makeresults | eval label=\"Go >\"",
				"queryParameters": {
					"earliest": "-1m",
					"latest": "now"
				}
			}
		}
	},
